export default function HDRImage({ image_url }) {
  if (image_url === undefined) {
    image_url = "data:image/png;base64,";
  }

  return (
    <div style={{
      position: "relative",
      background: "black",
      width: "240px",
      height: "240px"
    }}>
      <video poster="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAABAAAAAQAQAAAAA3iMLMAAAAAXNSR0IArs4c6QAAAA5JREFUeNpj+P+fgRQEAP1OH+HeyHWXAAAAAElFTkSuQmCC" src="data:video/mp4;base64,"
        muted="muted"
        autoPlay="autoplay"
        playsInline=""
        style={{
          position: "absolute",
          top: "0",
          left: "0",
          width: "100%",
          height: "100%",
        }}></video>
      <img src={image_url}
        alt="Reference"
        style={{
          display: "block",
          position: "absolute",
          top: "0",
          left: "0",
          width: "100%",
          height: "100%",
        }}></img>
    </div>
  );
}
